import type {ComponentType} from 'react';
import React from 'react';
import {View} from 'react-native';
import {withOnyx} from 'react-native-onyx';
import type {OnyxEntry} from 'react-native-onyx';
import Button from '@components/Button';
import DotIndicatorMessage from '@components/DotIndicatorMessage';
import Form from '@components/Form';
import PressableWithFeedback from '@components/Pressable/PressableWithFeedback';
import Text from '@components/Text';
import withLocalize from '@components/withLocalize';
import type {WithLocalizeProps} from '@components/withLocalize';
import useNetwork from '@hooks/useNetwork';
import useThemeStyles from '@hooks/useThemeStyles';
import * as ErrorUtils from '@libs/ErrorUtils';
import * as Session from '@userActions/Session';
import redirectToSignIn from '@userActions/SignInRedirect';
import CONST from '@src/CONST';
import ONYXKEYS from '@src/ONYXKEYS';
import type {Account} from '@src/types/onyx';
import {isEmptyObject} from '@src/types/utils/EmptyObject';

type UnlinkLoginFormOnyxProps = {
    /** State for the account */
    account: OnyxEntry<Account>;
};

type UnlinkLoginFormProps = UnlinkLoginFormOnyxProps & WithLocalizeProps;

type UnlinkLoginFormState = {
    successMessage: string;
};

class UnlinkLoginForm extends React.Component<UnlinkLoginFormProps, UnlinkLoginFormState> {
    constructor(props: UnlinkLoginFormProps) {
        super(props);

        this.state = {
            successMessage: '',
        };
    }

    componentDidUpdate(prevProps: UnlinkLoginFormProps) {
        if (this.props.preferredLocale !== prevProps.preferredLocale && this.props.account?.message) {
            const isSuccessfulUnlink = this.props.account.message === 'unlinkLoginForm.linkSent' || this.props.account.message === 'unlinkLoginForm.succesfullyUnlinkedLogin';
            if (isSuccessfulUnlink) {
                this.setState({successMessage: this.props.translate(this.props.account.message)});
            }
        }
        if (this.props.account?.message === prevProps.account?.message || !this.props.account?.message) {
            return;
        }

        const isSuccessfulUnlink = this.props.account.message === 'unlinkLoginForm.linkSent' || this.props.account.message === 'unlinkLoginForm.succesfullyUnlinkedLogin';
        if (isSuccessfulUnlink) {
            this.setState({successMessage: this.props.translate(this.props.account.message)});
        }
    }

    render() {
        return (
            <UnlinkLoginFormWithHooks
                {...this.props}
                successMessage={this.state.successMessage}
            />
        );
    }
}

type UnlinkLoginFormWithHooksProps = UnlinkLoginFormProps & {
    successMessage: string;
};

function UnlinkLoginFormWithHooks({account, translate, successMessage}: UnlinkLoginFormWithHooksProps) {
    const styles = useThemeStyles();
    const {isOffline} = useNetwork();
    const unlinkMessage = successMessage || account?.message;

    return (
        <>
            <View style={[styles.mt5]}>
                <Text>{translate('unlinkLoginForm.confirmUnlinkYourLogin')}</Text>
            </View>

            {!!unlinkMessage && (
                // DotIndicatorMessage mostly expects onyxData errors, so we need to mock an object so that the messages looks similar to prop.account.errors
                <DotIndicatorMessage
                    style={[styles.mb5, styles.flex0]}
                    type="success"
                    // eslint-disable-next-line @typescript-eslint/naming-convention
                    messages={{0: unlinkMessage}}
                />
            )}
            {!!account?.errors && !isEmptyObject(account.errors) && (
                <DotIndicatorMessage
                    style={[styles.mb5]}
                    type="error"
                    messages={ErrorUtils.getErrorsWithTranslationData(account.errors)}
                />
            )}
            <Form
                formID={ONYXKEYS.FORMS.UNLINK_LOGIN_FORM}
                onSubmit={Session.requestUnlinkValidationLink}
                submitButtonText={translate('unlinkLoginForm.unlink')}
                style={[styles.mt5]}
                isSubmitButtonVisible={!successMessage}
                enabledWhenOffline
            >
                <PressableWithFeedback
                    accessibilityLabel={translate('common.back')}
                    onPress={() => redirectToSignIn()}
                >
                    <Text style={[styles.link]}>{translate('common.back')}</Text>
                </PressableWithFeedback>
                {!successMessage && (
                    <Button
                        success
                        text={translate('unlinkLoginForm.unlink')}
                        isLoading={account?.isLoading && account.loadingForm === CONST.FORMS.UNLINK_LOGIN_FORM}
                        onPress={() => Session.requestUnlinkValidationLink()}
                        isDisabled={!!isOffline || !!account?.message}
                    />
                )}
            </Form>
        </>
    );
}

UnlinkLoginFormWithHooks.displayName = 'UnlinkLoginFormWithHooks';

export default withLocalize(
    withOnyx<UnlinkLoginFormProps, UnlinkLoginFormOnyxProps>({
        account: {key: ONYXKEYS.ACCOUNT},
    })(UnlinkLoginForm),
);

